CREATE POLICY "Delete sale items" ON public."sale_items" AS permissive FOR DELETE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM sales s
  WHERE ((s.id = sale_items.sale_id) AND ((s.operator_id = auth.uid()) OR is_admin(auth.uid()))))));
